def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_prev, opp_prev = history[-1]

    # Counts
    opp_c = 0
    my_c = 0
    opp_d = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0

    for mine, opp in history:
        if mine == 'C':
            my_c += 1
        else:
            my_d += 1
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if mine == 'C' and opp == 'C':
            cc += 1
        elif mine == 'C' and opp == 'D':
            cd += 1
        elif mine == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    # Recent window
    w = history[-8:] if n >= 8 else history
    w_len = len(w)
    w_opp_c = 0
    w_opp_d = 0
    w_my_d = 0
    for mine, opp in w:
        if opp == 'C':
            w_opp_c += 1
        else:
            w_opp_d += 1
        if mine == 'D':
            w_my_d += 1

    # Consecutive opponent defections / cooperations at end
    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    consec_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_opp_c += 1
        else:
            break

    # Opponent cooperation rate
    opp_coop_rate = opp_c / float(n)

    # Fraction of opponent moves that were D right after our D
    opp_after_my_d_total = 0
    opp_after_my_d_c = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            opp_after_my_d_total += 1
            if history[i][1] == 'C':
                opp_after_my_d_c += 1

    # Early game: establish cooperation, but start probing slightly earlier
    # to gather information without destroying TFT-like opponents.
    if n <= 2:
        return 'C'

    # Strong endgame exploitation against cooperative opponents.
    remaining = 100 - n
    if remaining <= 1:
        # Last round: defect if opponent likely cooperates.
        if opp_coop_rate >= 0.5 or consec_opp_c >= 1:
            return 'D'
        if w_opp_c >= w_opp_d:
            return 'D'
        return 'D'

    if remaining <= 4:
        if opp_coop_rate >= 0.6 or consec_opp_c >= 2:
            return 'D'
        if w_opp_c > w_opp_d:
            return 'D'
        if opp_prev == 'D' and consec_opp_d >= 2:
            return 'C'
        return 'D'

    if remaining <= 9:
        if opp_coop_rate >= 0.65:
            return 'D'
        if consec_opp_c >= 3:
            return 'D'
        if w_opp_c >= 5:
            return 'D'
        if opp_prev == 'C':
            return 'C'
        if consec_opp_d >= 3:
            return 'D'
        return 'C'

    # Detect all-D: never reward it, but occasionally test if not obviously hopeless.
    if n >= 6 and opp_d == n:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Near all-D.
    if n >= 8 and opp_coop_rate <= 0.1:
        if n % 9 == 0:
            return 'C'
        return 'D'

    # Near all-C: exploit moderately, but maintain enough cooperation to
    # preserve the relationship and guard against hidden retaliation.
    if n >= 8 and opp_d <= 1:
        if opp_d == 0:
            if n >= 17 and n % 6 == 0:
                return 'D'
            if n >= 40 and rng.random() < 0.12:
                return 'D'
            return 'C'
        # One defection from opponent so far: gentler.
        if opp_prev == 'D' and consec_opp_d >= 2:
            return 'D'
        if n >= 15 and n % 7 == 0:
            return 'D'
        return 'C'

    # If opponent has defected many times in a row, retaliate.
    if consec_opp_d >= 3:
        if opp_coop_rate >= 0.7 and consec_opp_d == 3:
            return 'C'
        return 'D'

    # If opponent defected last:
    if opp_prev == 'D':
        # Forgiving if opponent is overall cooperative and not persistently defecting.
        if opp_coop_rate >= 0.72 and consec_opp_d == 1:
            if w_opp_c >= 5:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if opp_coop_rate >= 0.55 and consec_opp_d == 1 and w_opp_c >= 4:
            if my_prev == 'D' and dd >= 1:
                return 'C'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # If our recent defections seem to be provoking opponent D, forgive.
        if dc >= 1 and my_d >= 2 and w_my_d >= 2 and opp_coop_rate >= 0.4:
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we just defected and opponent still cooperated, consider pressing
    # the advantage or returning to cooperation, depending on cooperation level.
    if my_prev == 'D':
        if opp_coop_rate >= 0.8:
            if n < 85 and n % 5 == 0:
                return 'D'
            return 'C'
        if opp_coop_rate >= 0.55 and w_opp_d <= 1:
            if n < 80 and n % 6 == 0:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated last.
    # Against very cooperative opponents, occasional probing increases score
    # but only if they do not retaliate harshly.
    if opp_coop_rate >= 0.85 and n >= 10:
        if opp_after_my_d_total >= 2:
            forgive_rate = opp_after_my_d_c / float(opp_after_my_d_total)
            if forgive_rate >= 0.7:
                if n % 5 == 0:
                    return 'D'
            elif forgive_rate >= 0.4:
                if n % 9 == 0:
                    return 'D'
        else:
            if n % 7 == 0:
                return 'D'
        return 'C'

    if opp_coop_rate >= 0.65 and n >= 12:
        if consec_opp_c >= 5 and n % 6 == 0:
            return 'D'
        if n % 13 == 0 and opp_coop_rate >= 0.75:
            return 'D'
        return 'C'

    # Moderate cooperation: reciprocal with light forgiveness.
    if opp_coop_rate >= 0.45:
        if w_opp_d >= 3 and w_opp_c <= 3:
            return 'D'
        return 'C'

    # Mostly defecting opponent.
    if opp_coop_rate <= 0.25:
        if n % 7 == 0 and opp_prev == 'C':
            return 'C'
        return 'D'

    # Ambiguous middle: retaliate if recent defections, otherwise cooperate.
    if w_opp_d >= 3:
        return 'D'
    if w_opp_c >= 4:
        return 'C'
    return 'C' if rng.random() < 0.55 else 'D'
